input.new_string:
.testimonials-mark {
    text-align: center;
    margin-bottom: 50px;
    font-size: 2.5rem;
    color: #9c7c57;
    font-family: Georgia, serif;
}

.carousel-wrapper {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 30px;
}

.carousel-nav {
    background: none;
    border: none;
    color: #9c7c57;
    font-size: 2rem;
    cursor: pointer;
    transition: color 0.3s ease;
    padding: 0;
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.carousel-nav:hover {
    color: #c9ab81;
}

.carousel-prev, .carousel-next {
    flex-shrink: 0;
}

.testimonial-carousel {
    position: relative;
    flex: 1;
}
